-- Clearwater, Florida fence-rule seed v1.
-- Data-only migration; public.municipalities is intentionally untouched.
begin;
set constraints all deferred;













update public.rule_versions rv set lifecycle_status='active', effective_from=date '2026-08-23', verified_at=timestamptz '2026-08-23 00:00:00+00', published_at=timestamptz '2026-08-23 00:00:00+00' from public.rules r join public.rule_sets rs on rs.id=r.rule_set_id where rv.rule_id=r.id and rs.key='clearwater_fence_v1' and rv.version_number=1 and rv.published_at is null;
update public.rules r set active_version_id=rv.id from public.rule_versions rv, public.rule_sets rs where rv.rule_id=r.id and rs.id=r.rule_set_id and rs.key='clearwater_fence_v1' and rv.version_number=1 and rv.lifecycle_status='active' and rv.published_at is not null and r.active_version_id is distinct from rv.id;

-- Supported precedence/dependency relationships.

commit;
