insert into public.jurisdictions (slug,name,jurisdiction_type,state_code,reference_metadata) values ('clearwater-fl','Clearwater, Florida','municipality','FL','{"research_package":"research/clearwater/fence-rule-package-v1.md"}') on conflict (slug) do nothing;
insert into public.project_types (key,label,description) values ('fence','Fence / fencing','Construction, placement, alteration, repair, and maintenance of fences and walls.') on conflict (key) do nothing;
insert into public.rule_sets (jurisdiction_id,project_type_id,key,title,scope_description,coverage_status,research_status,effective_from,verified_at,published_at,known_gaps) select j.id,p.id,'clearwater_fence_v1','Clearwater fence rules v1','Supported Clearwater Community Development Code fence and wall provisions plus the narrow Code of Ordinances barbed-wire rule. Absence of a rule is not permission.','limited','verified',date '2026-08-23',timestamptz '2026-08-23 00:00:00+00',timestamptz '2026-08-23 00:00:00+00','["Sight-triangle horizontal geometry","Pool-barrier technical authority","Ordinary permit requirements","Special district/overlay standards","Parcel-specific authoritative inputs","Barbed-wire provision interaction"]'::jsonb from public.jurisdictions j cross join public.project_types p where j.slug='clearwater-fl' and p.key='fence' on conflict (jurisdiction_id,project_type_id,key) do nothing;
insert into public.regulatory_sources (jurisdiction_id,source_type,title,issuing_body,edition_label,published_on,verified_at,notes,source_metadata) select j.id,v.source_type,v.title,'City of Clearwater',v.edition_label,v.published_on,timestamptz '2026-08-23 00:00:00+00',v.notes,v.metadata from public.jurisdictions j cross join (values ('code','Clearwater Community Development Code','Volume II, Supplement No. 55 (July 2026)',null::date,'Compilation states ordinances through Ordinance No. 9857-25, enacted December 4, 2025; the exact supplement publication day and provision effective dates were not independently established.','{"cutoff_ordinance":"9857-25","cutoff_enacted_on":"2025-12-04","supplement_month":"2026-07"}'::jsonb),('code','Clearwater Code of Ordinances',null::text,null::date,'Supplemental source retained from prior repository research; edition, retrieval date, and canonical URL were not supported by the package.','{"currentness":"limited","scope":"supported special cases only"}'::jsonb)) v(source_type,title,edition_label,published_on,notes,metadata) where j.slug='clearwater-fl' on conflict (jurisdiction_id,title,(coalesce(edition_label,''))) do nothing;
insert into public.source_provisions (regulatory_source_id,locator,display_locator,title,excerpt,verified_at,notes) select s.id,v.locator,v.display_locator,v.title,v.excerpt,timestamptz '2026-08-23 00:00:00+00','Minimally sufficient reconstruction from fence-rule-package-v1; consult official code text before legal reliance.' from (values ('Clearwater Community Development Code','3-801','§ 3-801','Purpose and applicability','Division 8 provides standards for fences and walls.'),('Clearwater Community Development Code','3-802','§ 3-802','Materials','Fence materials must be appropriate; walls need decorative finish; corrugated or sheet metal and injurious techniques are prohibited; wire fences must use chain-link and may not expose top points, wires, or prongs, subject to the unresolved barbed-wire provision.'),('Clearwater Community Development Code','3-803','§ 3-803','Design requirements','Required-setback fences have finished-side, inward-support, maintenance-access, and visibility duties; street-facing planes over 100 feet require qualifying insets, openings, or architectural treatment.'),('Clearwater Community Development Code','3-804','§ 3-804','Height requirements','Non-chain-link fences use the front, side/rear, waterfront, lot-type, retaining-wall, combined-height, and entry-component standards stated in this section.'),('Clearwater Community Development Code','3-805','§ 3-805','Chainlink fences','Chain-link is prohibited Downtown and is subject to front-location, height, public-right-of-way, landscaping, recreation, vacant-lot, and public-landbank provisions.'),('Clearwater Community Development Code','3-806','§ 3-806','Easements and rights-of-way','Fences may not occupy specified rights-of-way/easements or enclose meters/manholes without authorization; utility-easement placement requires suitable access and preserves removal rights.'),('Clearwater Community Development Code','3-807','§ 3-807','Special regulations','This section addresses pool enclosures, visibility, subdivision plans/perimeters, and Building Official approval of temporary construction fencing.'),('Clearwater Community Development Code','3-808','§ 3-808','Maintenance of fences and walls','Fences must be maintained, may not lean or sag over ten degrees unless designed and permitted, and nonconforming-fence boards may be replaced if posts are not replaced.'),('Clearwater Community Development Code','3-904','§ 3-904','Sight visibility triangles','Street/driveway visibility is protected between 30 inches and eight feet; a waterfront triangle permits only a non-opaque fence no higher than 48 inches among the stated exceptions. Official figure geometry is not in the extraction.'),('Clearwater Community Development Code','3-1202.F','§ 3-1202.F','Landscape strips','A referenced landscape strip is outside the right-of-way and uses a solid hedge or a qualifying mix installed for coverage at maturity.'),('Clearwater Community Development Code','8-102','§ 8-102','Definitions','Defines relevant terms including easement, structure height, lot types, opaque, principal structure, property lines, right-of-way, and setbacks.'),('Clearwater Code of Ordinances','28.06','§ 28.06','Barbed wire near streets','Building or repairing a barbed-wire fence adjacent to a street, alley, or sidewalk is unlawful; adjacent is not quantified in the reviewed extract.')) v(source_title,locator,display_locator,title,excerpt) join public.regulatory_sources s on s.title=v.source_title join public.jurisdictions j on j.id=s.jurisdiction_id and j.slug='clearwater-fl' on conflict (regulatory_source_id,locator) do nothing;
