insert into public.rules (rule_set_id,key,title,legacy_key,group_key) select rs.id,v.key,v.title,v.candidates,v.group_key from (values ('material.metal_prohibition','Corrugated and sheet metal prohibition','CLR-FENCE-001:material.metal_prohibition','material'),('material.wire_chain_link_required','Wire fence must use chain-link wire','CLR-FENCE-002 (split):material.wire_chain_link_required','material'),('material.exposed_top_prohibition','Exposed top points, wires, and prongs prohibited','CLR-FENCE-002 (split):material.exposed_top_prohibition','material'),('design.finished_side','Finished-side orientation','CLR-FENCE-003 (split):design.finished_side','design'),('design.support_orientation','Post and stringer orientation','CLR-FENCE-003 (split):design.support_orientation','design'),('design.long_street_plane','Long street-facing plane treatment','CLR-FENCE-004:design.long_street_plane','design'),('height.front_baseline','Ordinary front maximum height','CLR-FENCE-005:height.front_baseline','height'),('design.front_landscape_strip','Landscape strip for fences over three feet','CLR-FENCE-006:design.front_landscape_strip','design'),('height.side_rear_baseline','Ordinary side and rear maximum height','CLR-FENCE-007:height.side_rear_baseline','height'),('height.irt_side_rear','IRT side and rear maximum height','CLR-FENCE-008:height.irt_side_rear','height'),('waterfront.opacity','Waterfront protected-area opacity','CLR-FENCE-009 (split):waterfront.opacity','waterfront'),('waterfront.height','Waterfront protected-area maximum height','CLR-FENCE-009 (split):waterfront.height','waterfront'),('height.attached_dwelling','Attached-dwelling lot maximum height','CLR-FENCE-010:height.attached_dwelling','height'),('height.retaining_wall','Retaining-wall above-grade maximum','CLR-FENCE-011:height.retaining_wall','height'),('height.combined_components','Combined component maximum','CLR-FENCE-012:height.combined_components','height'),('entry.height','Entry component overall height','CLR