insert into public.rule_relationships (from_rule_id,to_rule_id,relationship_type,rationale,source_provision_id,effective_from,metadata) select fr.id,tr.id,v.rel,v.rationale,sp.id,date '2026-08-23',v.metadata from (values ('waterfront.height','height.side_rear_baseline','more_specific_than','The waterfront maximum is the specific side/rear rule.','{"candidate":"CLR-FENCE-009"}'::jsonb,'3-804'),('chain_link.side_rear_base_height','height.side_rear_baseline','more_specific_than','Section 3-805 governs chain-link instead of the ordinary schedule.','{"candidate":"CLR-FENCE-016"}'::jsonb,'3-805'),('chain_link.side_rear_vinyl_height','chain_link.side_rear_base_height','more_specific_than','Vinyl cladding supplies the stated six-foot chain-link pathway.','{"candidate":"CLR-FENCE-016"}'::jsonb,'3-805'),('chain_link.recreation_exemption','chain_link.front_location','exempts_from','The recreation provision expressly exempts the front-location restriction.','{"candidate":"CLR-FENCE-035"}'::jsonb,'3-805'),('chain_link.public_landbank','chain_link.landscaping','exempts_from','The public-landbank provision expressly exempts landscaping.','{"candidate":"CLR-FENCE-018"}'::jsonb,'3-805'),('material.exposed_top_prohibition','barbed_wire.street_adjacency','potentially_conflicts_with','The package flags unresolved interaction between the CDC top-wire prohibition and conditional barbed-wire treatment.','{"research_gap":"barbed_wire_interaction"}'::jsonb,'3-802')) v(from_key,to_key,rel,rationale,metadata,locator) join public.rules fr on fr.key=v.from_key join public.rules tr on tr.key=v.to_key and tr.rule_set_id=fr.rule_set_id join public.rule_sets rs on rs.id=fr.rule_set_id and rs.key='clearwater_fence_v1' join public.source_provisions sp on sp.locator=v.locator join public.regulatory_sources s on s.id=sp.regulatory_source_id and s.jurisdiction_id=rs.jurisdiction_id where not exists (select 1 from public.rule_relationships rr where rr.from_rule_id=fr.id and rr.to_rule_id=tr.id and rr.relationship_type=v.rel and rr.effective_to is null);
